style:
/* 素白 —— 右上角英文标头，中英双行模块标题，日期独立左栏 */

.tw-subai.layout-academic.resume-paper .paper-flow::before {
  content: "PERSONAL RESUME";
  display: block;
  margin-bottom: 6mm;
  padding-bottom: 1.8mm;
  border-bottom: 0.25mm solid #cfdae1;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 0.92);
  font-weight: 700;
  letter-spacing: 0.34em;
  text-align: right;
}

.tw-subai.layout-academic.resume-paper .paper-header {
  margin-bottom: 6.5mm;
  padding-bottom: 4mm;
  border-bottom: 0.25mm solid #dbe4ea;
}

.tw-subai.layout-academic.resume-paper .paper-header--photo {
  align-items: flex-start;
  gap: 7mm;
}

.tw-subai.layout-academic.resume-paper .paper-header__main {
  flex: 1 1 auto;
  min-width: 0;
  padding-top: 2mm;
}

.tw-subai.layout-academic.resume-paper .paper-photo {
  order: -1;
  width: 23mm;
  height: 31mm;
  border: none;
  border-radius: 0;
  box-shadow: none;
}

.tw-subai.layout-academic.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #eef3f6;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-subai.layout-academic.resume-paper .paper-name {
  color: #1b2a33;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.05);
  letter-spacing: 0.04em;
}

.tw-subai.layout-academic.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #6b7c85;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-subai.layout-academic.resume-paper .paper-role {
  margin-top: 1.6mm;
  color: #54666f;
  font-size: calc(var(--paper-base-size) * 0.94);
  font-weight: 400;
  letter-spacing: 0.02em;
}

.tw-subai.layout-academic.resume-paper .paper-contacts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.2mm 8mm;
  margin-top: 3mm;
  color: #33454e;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-subai.layout-academic.resume-paper .paper-contact {
  display: flex;
  gap: 1.6mm;
}

.tw-subai.layout-academic.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-subai.layout-academic.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: var(--paper-accent);
}

/* 标题：蓝字 + 灰色英文副名 + 发丝线 */
.tw-subai.layout-academic.resume-paper .paper-style-caps .paper-section__title {
  display: flex;
  align-items: baseline;
  gap: 3mm;
  margin-bottom: 3mm;
  padding-bottom: 1.3mm;
  border-bottom: 0.25mm solid #d8e2e8;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 1.08);
  letter-spacing: 0.1em;
  text-transform: none;
}

.tw-subai.layout-academic.resume-paper .paper-style-caps .paper-section__title span {
  display: inline-flex;
  align-items: baseline;
  gap: 3mm;
}

.tw-subai.layout-academic.resume-paper .paper-style-caps .paper-section__title span::after {
  color: #93a3ac;
  font-size: calc(var(--paper-base-size) * 0.86);
  font-style: italic;
  font-weight: 400;
  letter-spacing: 0.04em;
}

.tw-subai.layout-academic.resume-paper .paper-style-caps .paper-section__title::after {
  display: none;
}

.tw-subai.layout-academic.resume-paper .is-education .paper-section__title span::after { content: "Education"; }
.tw-subai.layout-academic.resume-paper .is-work_experience .paper-section__title span::after { content: "Experience"; }
.tw-subai.layout-academic.resume-paper .is-project_experience .paper-section__title span::after { content: "Projects"; }
.tw-subai.layout-academic.resume-paper .is-campus_experience .paper-section__title span::after { content: "Schools"; }
.tw-subai.layout-academic.resume-paper .is-award .paper-section__title span::after { content: "Certificate"; }
.tw-subai.layout-academic.resume-paper .is-competition .paper-section__title span::after { content: "Contest"; }
.tw-subai.layout-academic.resume-paper .is-certificate .paper-section__title span::after { content: "Certificate"; }
.tw-subai.layout-academic.resume-paper .is-skills_summary .paper-section__title span::after { content: "Skills"; }
.tw-subai.layout-academic.resume-paper .is-skill_proficiency .paper-section__title span::after { content: "Proficiency"; }
.tw-subai.layout-academic.resume-paper .is-self_evaluation .paper-section__title span::after { content: "Assessment"; }
.tw-subai.layout-academic.resume-paper .is-job_intention .paper-section__title span::after { content: "Objective"; }
.tw-subai.layout-academic.resume-paper .is-paper_publication .paper-section__title span::after { content: "Publications"; }
.tw-subai.layout-academic.resume-paper .is-journal_paper .paper-section__title span::after { content: "Journals"; }
.tw-subai.layout-academic.resume-paper .is-portfolio .paper-section__title span::after { content: "Portfolio"; }
.tw-subai.layout-academic.resume-paper .is-hobby .paper-section__title span::after { content: "Interests"; }
.tw-subai.layout-academic.resume-paper .is-custom .paper-section__title span::after { content: ""; }

/* 条目：日期左栏更宽，专业与学位贴右 */
.tw-subai.layout-academic.resume-paper .paper-item {
  display: grid;
  grid-template-columns: 31mm minmax(0, 1fr);
  column-gap: 4mm;
  align-items: start;
}

.tw-subai.layout-academic.resume-paper .paper-item-head {
  display: contents;
}

.tw-subai.layout-academic.resume-paper .paper-item-period {
  grid-column: 1;
  grid-row: 1 / span 6;
  padding-top: 0.4mm;
  color: #7d8d96;
  font-size: calc(var(--paper-base-size) * 0.82);
  line-height: 1.5;
  white-space: nowrap;
}

.tw-subai.layout-academic.resume-paper .paper-item-title,
.tw-subai.layout-academic.resume-paper .paper-facts {
  grid-column: 2;
  grid-row: 1;
  color: #22333d;
  font-size: calc(var(--paper-base-size) * 1.02);
}

.tw-subai.layout-academic.resume-paper .paper-item-sub {
  grid-column: 2;
  grid-row: 1;
  justify-self: end;
  align-self: start;
  margin-top: 1.2mm;
  color: #7a8b94;
  font-size: calc(var(--paper-base-size) * 0.86);
  font-weight: 400;
}

.tw-subai.layout-academic.resume-paper .paper-meta-line,
.tw-subai.layout-academic.resume-paper .paper-note,
.tw-subai.layout-academic.resume-paper .paper-rich {
  grid-column: 2;
  grid-row: auto;
}

.tw-subai.layout-academic.resume-paper .paper-item-sub span + span::before {
  content: " / ";
  margin: 0 0.6mm;
  color: #c2ced5;
}

.tw-subai.layout-academic.resume-paper .paper-rich ul,
.tw-subai.layout-academic.resume-paper .paper-rich ol {
  margin-top: 1mm;
  padding-left: 0;
  list-style: none;
}

.tw-subai.layout-academic.resume-paper .paper-rich li {
  position: relative;
  margin: 0.8mm 0;
  padding-left: 3.4mm;
}

.tw-subai.layout-academic.resume-paper .paper-rich li::before {
  content: "";
  position: absolute;
  top: 0.62em;
  left: 0.4mm;
  width: 1mm;
  height: 1mm;
  border-radius: 50%;
  background: #a8b8c0;
  print-color-adjust: exact;
}

.tw-subai.layout-academic.resume-paper .paper-note__tag {
  color: #22333d;
  font-weight: 600;
}

.tw-subai.layout-academic.resume-paper .paper-footer {
  border-top: 0.2mm solid #e0e8ec;
  color: #9dabb3;
}
